# NOTE: THIS SOURCE FILE WAS GENERATED BY CLAUDE OPUS 5.5 WITH LITTLE HUMAN OVERSIGHT
# PLEASE REVIEW THE AI POLICY AT REPOSITORY ROOT FOR MORE INFORMATION
"""
Write a bare-bones .html twin of every tutor text file (tutor.txt -> tutor.html, etc.).

Some chatbots (ChatGPT in particular) won't follow a URL written as plain text inside a
fetched file, but will follow a real <a href> link. So each twin is the text in a <pre>,
with every URL and every reference to another tutor file turned into a link to its .html
twin. The .txt/.md files stay the source of truth; edit those, then rerun this.

Run from anywhere: python3 build_html.py  (the regenerate scripts also run it)
"""

import html
import pathlib
import re

SITE = pathlib.Path(__file__).resolve().parents[3] / "scamp_tutor" / "tutor"
BASE_URL = "https://marcthespark.github.io/scamp-tutor/"

SOURCES = sorted(
    [SITE / n for n in ("tutor.txt", "resources.txt", "stumblingBlocks.txt")]
    + list((SITE / "docs").glob("*.txt"))
    + list((SITE / "examples").glob("*.txt"))
    + list((SITE / "examples").glob("*.md"))
)
# relative path of each source -> relative path of its twin
TWINS = {p.relative_to(SITE).as_posix(): p.relative_to(SITE).with_suffix(".html").as_posix()
         for p in SOURCES}

URL = r"https?://[^\s<>\"']+"
# a bare tutor file reference, not part of a longer path or word
REF = r"(?<![\w/.-])(?:" + "|".join(re.escape(r) for r in sorted(TWINS, key=len, reverse=True)) \
      + r")(?![\w/-])"
LINK_RE = re.compile(f"({URL})|({REF})")

PAGE = """<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>{title}</title>
<style>pre {{ white-space: pre-wrap; }}</style>
</head>
<body>
<pre>{body}</pre>
</body>
</html>
"""


def linkify(match):
    url, ref = match.group(1), match.group(2)
    if ref:
        twin = TWINS[ref]
        return f'<a href="{BASE_URL}{twin}">{twin}</a>'
    trail = re.search(r"[.,;:)]*$", url).group()
    url = url[:len(url) - len(trail)]
    rest = url[len(BASE_URL):] if url.startswith(BASE_URL) else None
    if rest in TWINS:
        url = BASE_URL + TWINS[rest]
    return f'<a href="{url}">{url}</a>{trail}'


def main():
    for src in SOURCES:
        rel = src.relative_to(SITE).as_posix()
        body = LINK_RE.sub(linkify, html.escape(src.read_text(), quote=False))
        (SITE / TWINS[rel]).write_text(PAGE.format(title=html.escape(rel), body=body))
    print(f"wrote {len(SOURCES)} .html twins")


if __name__ == "__main__":
    main()
